      // Never add a tab, load a saved URL, select a tab or reload a running page.
      if (!enabled() || !eligible(tab) || !selected(tab) || attempted.has(tab))
        return;
      if (!sleeping(tab)) {
        attempted.add(tab);
        return;
      }
